function validateUser(u: any) {
  const errors: string[] = [];
  if (!u.email) errors.push('email required');
  if (!isValidPassword(u.password)) errors.push('password weak');
  // other checks
  if (errors.length) return { ok: false, errors };
  createAccount(u);
  return { ok: true };
}

// Version A: strict validation and explicit errors
function parseConfigA(raw: any): Config {
  if (!raw.host) throw new Error('host missing');
  if (typeof raw.port !== 'number') throw new Error('invalid port');
  return { host: raw.host, port: raw.port };
}

// Version B: permissive partial return
function parseConfigB(raw: any): Partial<Config> {
  const result: Partial<Config> = {};
  if (raw.host) result.host = raw.host;
  if (typeof raw.port === 'number') result.port = raw.port;
  return result;
}
